package net.zartra.gui;
import org.bukkit.Color;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.meta.ItemMeta;
final class LeatherColorCompat{private LeatherColorCompat(){}static boolean capable(MenuItem item){try{return capable(item.stack());}catch(Throwable ignored){return false;}}static boolean capable(ItemStack stack){if(stack==null)return false;try{ItemMeta meta=stack.getItemMeta();return meta!=null&&meta.getClass().getMethod("setColor",Color.class)!=null&&meta.getClass().getMethod("getColor")!=null;}catch(Throwable ignored){return false;}}static int[] rgb(String value){try{String[] p=value.split(",");if(p.length!=3)return null;int[] out=new int[3];for(int n=0;n<3;n++){out[n]=Integer.parseInt(p[n]);if(out[n]<0||out[n]>255)return null;}return out;}catch(Exception ignored){return null;}}static String hex(String value){int[] rgb=rgb(value);return rgb==null?"#A06540":String.format("#%02X%02X%02X",rgb[0],rgb[1],rgb[2]);}static ItemStack dyed(ItemStack source,String value,boolean reset){ItemStack out=source.clone();try{ItemMeta meta=out.getItemMeta();if(meta==null)return out;java.lang.reflect.Method set=meta.getClass().getMethod("setColor",Color.class);if(reset){ItemStack clean=new ItemStack(out.getType());ItemMeta plain=clean.getItemMeta();Color color=(Color)plain.getClass().getMethod("getColor").invoke(plain);set.invoke(meta,color);}else{int[] rgb=rgb(value);if(rgb!=null)set.invoke(meta,Color.fromRGB(rgb[0],rgb[1],rgb[2]));}out.setItemMeta(meta);}catch(Throwable ignored){}return out;}}